window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-e3a9c293e2379113"]={"versions": [{"id": "FIG-e3a9c293e2379113", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Metamodells für die Attributanpassung (<code>AttributeTailoring</code>) innerhalb der AUTOSAR-Standardisierungs-Templates (TPS StandardizationTemplate). Es definiert die strukturellen Elemente zur Einschränkung und Anpassung von Modelleigenschaften (Multiplizität, Variabilität und Standardwertbehandlung) für standardisierte ASR-Klassendefinitionen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>ClassContentConditional</strong> (Spezialisierung von <code>Identifiable</code>): Aggregiert über die Kompositionsrolle <code>+attributeTailoring</code> mit Kardinalität <code>0..*</code> Instanzen von <code>AttributeTailoring</code>.\n</li><li><strong>AttributeTailoring</strong> (abstrakt, spezialisiert <code>DataFormatElementScope</code>): Abstrakte Basisklasse für Anpassungen von Attributen.\n<ul class=\"fig-list\"><li>Komposition <code>+multiplicityRestriction</code> mit Kardinalität <code>0..1</code> auf <code>MultiplicityRestrictionWithSeverity</code> (spezialisiert <code>AbstractMultiplicityRestriction</code>, <code>RestrictionWithSeverity</code>).\n</li><li>Komposition <code>+variationRestriction</code> mit Kardinalität <code>0..1</code> auf <code>VariationRestrictionWithSeverity</code> (spezialisiert <code>AbstractVariationRestriction</code>, <code>RestrictionWithSeverity</code>).\n</li></ul>\n</li><li><strong>Spezialisierungen von AttributeTailoring</strong>:\n<ul class=\"fig-list\"><li><code>AggregationTailoring</code>: Spezialisierung zur Anpassung von Aggregationen/Kompositionen.\n</li><li><code>ReferenceTailoring</code>: Spezialisierung zur Anpassung von Referenzen.\n</li><li><code>PrimitiveAttributeTailoring</code>: Spezialisierung zur Anpassung primitiver Attribute. Enthält das Attribut <code>+ defaultValueHandling :DefaultValueApplicationStrategyEnum [0..1]</code>. Besitzt eine rekursive gerichtete Assoziation auf sich selbst über die Rolle <code>+subAttributeTailoring</code> mit Kardinalität <code>0..*</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Sequenzabläufe oder Laufzeitinteraktionen. Die Instanziierung erfolgt deklarativ im Rahmen der Modell- und Profildefinition, wobei Restriktionen und Anpassungsregeln zur Entwurfs- bzw. Validierungszeit auf die jeweiligen Modellelemente angewendet werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Klassen und Assoziationen definieren normative Vorgaben für Modell-Validierungswerkzeuge. Konkret steuert <code>defaultValueHandling</code> die verbindliche Handhabung von Default-Werten primitiver Attribute. Die Restriktionsklassen <code>MultiplicityRestrictionWithSeverity</code> und <code>VariationRestrictionWithSeverity</code> ermöglichen die feingranulare Einschränkung von Kardinalitäten und Variationspunkten inklusive konfigurierbarem Schweregrad bei Verletzung der Vorgaben.</p>"}, {"id": "FIG-2f4ce8e6a9ced935", "releases": ["R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Metamodells für die Attributanpassung (<code>AttributeTailoring</code>) innerhalb der AUTOSAR-Standardisierungs-Templates (TPS StandardizationTemplate). Es definiert die strukturellen Elemente zur Einschränkung und Anpassung von Modelleigenschaften (Multiplizität, Variabilität und Standardwertbehandlung) für standardisierte ASR-Klassendefinitionen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>ClassContentConditional</strong> (Spezialisierung von <code>Identifiable</code>): Aggregiert über die Kompositionsrolle <code>+attributeTailoring</code> mit Kardinalität <code>0..*</code> Instanzen von <code>AttributeTailoring</code>.\n</li><li><strong>AttributeTailoring</strong> (abstrakt, spezialisiert <code>DataFormatElementScope</code>): Abstrakte Basisklasse für Anpassungen von Attributen.\n<ul class=\"fig-list\"><li>Komposition <code>+multiplicityRestriction</code> mit Kardinalität <code>0..1</code> auf <code>MultiplicityRestrictionWithSeverity</code> (spezialisiert <code>AbstractMultiplicityRestriction</code>, <code>RestrictionWithSeverity</code>).\n</li><li>Komposition <code>+variationRestriction</code> mit Kardinalität <code>0..1</code> auf <code>VariationRestrictionWithSeverity</code> (spezialisiert <code>AbstractVariationRestriction</code>, <code>RestrictionWithSeverity</code>).\n</li></ul>\n</li><li><strong>Spezialisierungen von AttributeTailoring</strong>:\n<ul class=\"fig-list\"><li><code>AggregationTailoring</code>: Spezialisierung zur Anpassung von Aggregationen/Kompositionen.\n</li><li><code>ReferenceTailoring</code>: Spezialisierung zur Anpassung von Referenzen.\n</li><li><code>PrimitiveAttributeTailoring</code>: Spezialisierung zur Anpassung primitiver Attribute. Enthält das Attribut <code>+ defaultValueHandling: DefaultValueApplicationStrategyEnum [0..1]</code>. Besitzt eine rekursive gerichtete Assoziation auf sich selbst über die Rolle <code>+subAttributeTailoring</code> mit Kardinalität <code>0..*</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Sequenzabläufe oder Laufzeitinteraktionen. Die Instanziierung erfolgt deklarativ im Rahmen der Modell- und Profildefinition, wobei Restriktionen und Anpassungsregeln zur Entwurfs- bzw. Validierungszeit auf die jeweiligen Modellelemente angewendet werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Klassen und Assoziationen definieren normative Vorgaben für Modell-Validierungswerkzeuge. Konkret steuert <code>defaultValueHandling</code> die verbindliche Handhabung von Default-Werten primitiver Attribute. Die Restriktionsklassen <code>MultiplicityRestrictionWithSeverity</code> und <code>VariationRestrictionWithSeverity</code> ermöglichen die feingranulare Einschränkung von Kardinalitäten und Variationspunkten inklusive konfigurierbarem Schweregrad bei Verletzung der Vorgaben.</p>"}, {"id": "FIG-17d51fdef9467544", "releases": ["R19-11", "R20-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Metamodells für die Attributanpassung (<code>AttributeTailoring</code>) innerhalb der AUTOSAR-Standardisierungs-Templates (TPS StandardizationTemplate). Es definiert die strukturellen Elemente zur Einschränkung und Anpassung von Modelleigenschaften (Multiplizität, Variabilität und Standardwertbehandlung) für standardisierte ASR-Klassendefinitionen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>ClassContentConditional</strong> (Spezialisierung von <code>Identifiable</code>): Aggregiert über die Kompositionsrolle <code>+attributeTailoring</code> mit Kardinalität <code>0..*</code> Instanzen von <code>AttributeTailoring</code>.\n</li><li><strong>AttributeTailoring</strong> (abstrakt, spezialisiert <code>DataFormatElementScope</code>): Abstrakte Basisklasse für Anpassungen von Attributen.\n<ul class=\"fig-list\"><li>Komposition <code>+multiplicityRestriction</code> mit Kardinalität <code>0..1</code> auf <code>MultiplicityRestrictionWithSeverity</code> (spezialisiert <code>AbstractMultiplicityRestriction</code>, <code>RestrictionWithSeverity</code>).\n</li><li>Komposition <code>+variationRestriction</code> mit Kardinalität <code>0..1</code> auf <code>VariationRestrictionWithSeverity</code> (spezialisiert <code>AbstractVariationRestriction</code>, <code>RestrictionWithSeverity</code>).\n</li></ul>\n</li><li><strong>Spezialisierungen von AttributeTailoring</strong>:\n<ul class=\"fig-list\"><li><code>AggregationTailoring</code>: Spezialisierung zur Anpassung von Aggregationen/Kompositionen.\n</li><li><code>ReferenceTailoring</code>: Spezialisierung zur Anpassung von Referenzen.\n</li><li><code>PrimitiveAttributeTailoring</code>: Spezialisierung zur Anpassung primitiver Attribute. Enthält das Attribut <code>+ defaultValueHandling: DefaultValueApplicationStrategyEnum [0..1]</code>. Besitzt eine rekursive gerichtete Assoziation auf sich selbst über die Rolle <code>+subAttributeTailoring</code> mit Kardinalität <code>0..*</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Sequenzabläufe oder Laufzeitinteraktionen. Die Instanziierung erfolgt deklarativ im Rahmen der Modell- und Profildefinition, wobei Restriktionen und Anpassungsregeln zur Entwurfs- bzw. Validierungszeit auf die jeweiligen Modellelemente angewendet werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Klassen und Assoziationen definieren normative Vorgaben für Modell-Validierungswerkzeuge. Konkret steuert <code>defaultValueHandling</code> die verbindliche Handhabung von Default-Werten primitiver Attribute. Die Restriktionsklassen <code>MultiplicityRestrictionWithSeverity</code> und <code>VariationRestrictionWithSeverity</code> ermöglichen die feingranulare Einschränkung von Kardinalitäten und Variationspunkten inklusive konfigurierbarem Schweregrad bei Verletzung der Vorgaben.</p>"}, {"id": "FIG-76b62d5db240b77e", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Metamodells für die Attributanpassung (<code>AttributeTailoring</code>) innerhalb der AUTOSAR-Standardisierungs-Templates (TPS StandardizationTemplate). Es definiert die strukturellen Elemente zur Einschränkung und Anpassung von Modelleigenschaften (Multiplizität, Variabilität und Standardwertbehandlung) für standardisierte ASR-Klassendefinitionen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>ClassContentConditional</strong> (Spezialisierung von <code>Identifiable</code>): Aggregiert über die Kompositionsrolle <code>+attributeTailoring</code> mit Kardinalität <code>0..*</code> Instanzen von <code>AttributeTailoring</code>.\n</li><li><strong>AttributeTailoring</strong> (abstrakt, spezialisiert <code>DataFormatElementScope</code>): Abstrakte Basisklasse für Anpassungen von Attributen.\n<ul class=\"fig-list\"><li>Komposition <code>+multiplicityRestriction</code> mit Kardinalität <code>0..1</code> auf <code>MultiplicityRestrictionWithSeverity</code> (spezialisiert <code>AbstractMultiplicityRestriction</code>, <code>RestrictionWithSeverity</code>).\n</li><li>Komposition <code>+variationRestriction</code> mit Kardinalität <code>0..1</code> auf <code>VariationRestrictionWithSeverity</code> (spezialisiert <code>AbstractVariationRestriction</code>, <code>RestrictionWithSeverity</code>).\n</li></ul>\n</li><li><strong>Spezialisierungen von AttributeTailoring</strong>:\n<ul class=\"fig-list\"><li><code>AggregationTailoring</code>: Spezialisierung zur Anpassung von Aggregationen/Kompositionen.\n</li><li><code>ReferenceTailoring</code>: Spezialisierung zur Anpassung von Referenzen.\n</li><li><code>PrimitiveAttributeTailoring</code>: Spezialisierung zur Anpassung primitiver Attribute. Enthält das Attribut <code>+ defaultValueHandling: DefaultValueApplicationStrategyEnum [0..1]</code>. Besitzt eine rekursive gerichtete Assoziation auf sich selbst über die Rolle <code>+subAttributeTailoring</code> mit Kardinalität <code>0..*</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Sequenzabläufe oder Laufzeitinteraktionen. Die Instanziierung erfolgt deklarativ im Rahmen der Modell- und Profildefinition, wobei Restriktionen und Anpassungsregeln zur Entwurfs- bzw. Validierungszeit auf die jeweiligen Modellelemente angewendet werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Klassen und Assoziationen definieren normative Vorgaben für Modell-Validierungswerkzeuge. Konkret steuert <code>defaultValueHandling</code> die verbindliche Handhabung von Default-Werten primitiver Attribute. Die Restriktionsklassen <code>MultiplicityRestrictionWithSeverity</code> und <code>VariationRestrictionWithSeverity</code> ermöglichen die feingranulare Einschränkung von Kardinalitäten und Variationspunkten inklusive konfigurierbarem Schweregrad bei Verletzung der Vorgaben.</p>"}], "trans": [{"from": "FIG-e3a9c293e2379113", "to": "FIG-2f4ce8e6a9ced935", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li><code>PrimitiveAttributeTailoring</code>: Im Attribut <code>defaultValueHandling</code> wurde der Abstand vor dem Doppelpunkt entfernt (<code>:DefaultValueApplicationStrategyEnum</code> zu <code>: DefaultValueApplicationStrategyEnum</code>).\n</li><li>Anordnung und Linienführung minimal neu gerendert (u. a. Kanten und Beschriftungspositionierung der Assoziationen).\n</li></ul>"}, {"from": "FIG-2f4ce8e6a9ced935", "to": "FIG-17d51fdef9467544", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-17d51fdef9467544", "to": "FIG-76b62d5db240b77e", "fr": "R21-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
